// Источник: кейс .qa/tests/auth-login/AL-03-relogin-after-logout.md, план .qa/e2e/specs/auth-login.md (web-автотеста нет).
// Тикет #6aa268eb (502 при повторном входе после Logout). Выход «התנתקות» → вход снова (login(), тестовый OTP) → главная, без ошибки.
// Проверка ответа dev-otp (200, нет 502) в Network — на устройстве не видна; признак успеха — открывшаяся главная.
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, tapLabel, scrollToText } from '../../helpers/ui.ts';
import { ensureAppReady, isLoggedIn, login, toHome } from '../../helpers/app.ts';

/** Выход: профиль → «התנתקות» (+ подтверждение, если есть) → splash. */
async function logout() {
  await toHome();
  await tapLabel('מעבר לפרטים שלי');
  await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
  await (await scrollToText('התנתקות')).click();
  await driver.waitUntil(async () => {
    if (await byText('בואו נתחיל').isDisplayed().catch(() => false)) return true;
    const confirm = await byText('התנתקות');
    if (await confirm.isDisplayed().catch(() => false)) await confirm.click().catch(() => {});
    return false;
  }, { timeout: 20000, interval: 700, timeoutMsg: 'после «התנתקות» не открылся splash' });
}
/** Вернуться к splash/входу и войти снова (login() начинает со splash или экрана номера). */
async function restoreLogin() {
  for (let i = 0; i < 4; i++) {
    if (await isLoggedIn()) return;
    if (await byText('בואו נתחיל').isDisplayed().catch(() => false)) break;
    if (await byText('כניסה דרך מספר נייד').isDisplayed().catch(() => false)) break;
    await driver.back();
  }
  await ensureAppReady();
}

describe('Вход по мобильному', () => {
  after(async () => { await restoreLogin(); });

  it('AL-03 Повторный вход после «התנתקות» — главная открывается, без ошибки #6aa268eb @prod-safe', async () => {
    // 1. Профиль → «התנתקות» → splash.
    await logout();
    // 2. Вход снова по номеру и коду.
    await login();
    // 3. Главная, нет сообщений об ошибке.
    await expect(byText('תזכורות מהירות')).toBeDisplayed();
    for (const err of ['502', 'create_failed', 'שגיאה']) await expect(byTextContains(err)).not.toBeDisplayed();
    // Сессия переживает перезапуск приложения.
    const id = driver.isAndroid ? process.env.APP_ANDROID_PACKAGE : process.env.APP_IOS_BUNDLE;
    if (id) {
      await driver.terminateApp(id);
      await driver.activateApp(id);
      await (await byText('בית')).waitForDisplayed({ timeout: 30000 });
    }
  });
});
